const KEY = 'starlight-high-score';
export function getHighScore(){ return Number(localStorage.getItem(KEY) || 0); }
export function saveHighScore(value){ const old=getHighScore(); if(value>old) localStorage.setItem(KEY,String(value)); return Math.max(old,value); }

export class Enemy{
  constructor(path, wave){ this.path=path; this.x=path[0].x; this.y=path[0].y; this.segment=0; this.hp=45+wave*13; this.maxHp=this.hp; this.speed=38+wave*2; this.radius=14; this.dead=false; this.reward=8+Math.floor(wave/2); this.slow=1; }
  update(dt){ if(this.dead)return 'dead'; this.slow=Math.min(1,this.slow+dt*.35); let remain=this.speed*this.slow*dt; while(remain>0 && this.segment<this.path.length-1){let p=this.path[this.segment+1],dx=p.x-this.x,dy=p.y-this.y,d=Math.hypot(dx,dy);if(d<=remain){this.x=p.x;this.y=p.y;this.segment++;remain-=d}else{this.x+=dx/d*remain;this.y+=dy/d*remain;remain=0}} if(this.segment>=this.path.length-1)return 'escaped'; return 'moving'; }
  damage(n,slow=false){this.hp-=n;if(slow)this.slow=.38;return this.hp<=0;}
  draw(ctx){ctx.beginPath();ctx.fillStyle='#ff7181';ctx.arc(this.x,this.y,this.radius,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ffd1d5';ctx.stroke();ctx.fillStyle='#161d2c';ctx.fillRect(this.x-18,this.y-25,36,5);ctx.fillStyle='#68e391';ctx.fillRect(this.x-18,this.y-25,36*Math.max(0,this.hp/this.maxHp),5);ctx.fillStyle='#fff';ctx.font='10px sans-serif';ctx.textAlign='center';ctx.fillText(Math.ceil(Math.max(0,this.hp)),this.x,this.y+4);}
}

export const TOWER_TYPES={blaster:{name:'블래스터',price:50,damage:12,range:125,rate:.55,color:'#65b8ff'},cannon:{name:'캐논',price:85,damage:28,range:105,rate:1.15,color:'#ffae65'},frost:{name:'프로스트',price:70,damage:8,range:145,rate:.7,color:'#69f0e2'}};
export class Tower{
 constructor(x,y,type){this.x=x;this.y=y;this.type=type;this.level=1;this.damage=TOWER_TYPES[type].damage;this.range=TOWER_TYPES[type].range;this.rate=TOWER_TYPES[type].rate;this.cool=0;this.totalCost=TOWER_TYPES[type].price;this.target=null;}
 update(dt,enemies,projectiles){this.cool-=dt;if(this.cool>0)return;let best=null,dist=Infinity;for(const e of enemies){let d=Math.hypot(e.x-this.x,e.y-this.y);if(!e.dead&&d<=this.range&&d<dist){best=e;dist=d}}if(best){this.target=best;this.cool=this.rate;projectiles.push({x:this.x,y:this.y,target:best,speed:430,damage:this.damage,color:TOWER_TYPES[this.type].color,slow:this.type==='frost'});}}
 upgrade(){let cost=this.upgradeCost();this.level++;this.damage=Math.round(this.damage*1.45);this.range+=12;this.totalCost+=cost;return cost}
 upgradeCost(){return 45+this.level*30}
 draw(ctx,selected){ctx.beginPath();ctx.fillStyle=TOWER_TYPES[this.type].color;ctx.arc(this.x,this.y,18,0,Math.PI*2);ctx.fill();ctx.fillStyle='#132035';ctx.fillRect(this.x-4,this.y-14,8,28);ctx.strokeStyle=selected?'#fff':'#17324c';ctx.lineWidth=selected?3:2;ctx.stroke();if(selected){ctx.beginPath();ctx.strokeStyle=this.color+'55';ctx.arc(this.x,this.y,this.range,0,Math.PI*2);ctx.stroke();}}
}
export function updateProjectiles(projectiles,dt,moneyRef){for(let i=projectiles.length-1;i>=0;i--){let p=projectiles[i],e=p.target;if(!e||e.dead){projectiles.splice(i,1);continue}let dx=e.x-p.x,dy=e.y-p.y,d=Math.hypot(dx,dy),step=p.speed*dt;if(d<=step){if(e.damage(p.damage,p.slow))moneyRef.value+=e.reward;p.hit=true;projectiles.splice(i,1)}else{p.x+=dx/d*step;p.y+=dy/d*step}}}
export function drawProjectiles(ctx,ps){for(const p of ps){ctx.beginPath();ctx.fillStyle=p.color;ctx.arc(p.x,p.y,5,0,Math.PI*2);ctx.fill();}}

import {getHighScore,saveHighScore} from './storage.js';import {Tower,TOWER_TYPES,updateProjectiles} from './tower.js';import {WaveManager} from './wave.js';import {drawScene,isOnPath} from './scene.js';import {UI} from './ui.js';
const ui=new UI(),canvas=document.getElementById('gameCanvas'),ctx=canvas.getContext('2d');ui.high.textContent=getHighScore();
const path=[{x:0,y:135},{x:185,y:135},{x:185,y:410},{x:430,y:410},{x:430,y:155},{x:690,y:155},{x:690,y:455},{x:900,y:455}];let towers=[],enemies=[],projectiles=[],money=220,lives=20,selectedType='blaster',selectedTower=null,paused=false,running=false,last=0,wave;
function reset(){towers=[];enemies=[];projectiles=[];money=220;lives=20;paused=false;running=true;wave=new WaveManager(path);ui.stats(money,lives,wave.number);document.getElementById('pausedLabel').classList.add('hidden');document.getElementById('pauseButton').textContent='Ⅱ 일시정지';last=0;requestAnimationFrame(loop)}
function loop(time){if(!running)return;if(!last)last=time;let dt=Math.min(.05,(time-last)/1000||0);last=time;if(!paused){wave.update(dt,enemies);for(const e of [...enemies]){let result=e.update(dt);if(result==='escaped'){enemies.splice(enemies.indexOf(e),1);lives--;ui.message('적이 끝에 도달했습니다! 목숨 -1');if(lives<=0){endGame();return}}}for(const t of towers)t.update(dt,enemies,projectiles);let wallet={value:money};updateProjectiles(projectiles,dt,wallet);money=wallet.value;for(let i=enemies.length-1;i>=0;i--)if(enemies[i].dead||enemies[i].hp<=0){money+=enemies[i].reward;enemies.splice(i,1)}if(wave.number!==Number(ui.wave.textContent))ui.message('다음 웨이브 시작!');ui.stats(money,lives,wave.number);if(!wave.active&&enemies.length===0){ui.message('10 웨이브 완주!');running=false;saveHighScore(10)}}drawScene(ctx,path,towers,enemies,projectiles,selectedTower);requestAnimationFrame(loop)}
function endGame(){running=false;let reached=wave?wave.number:1;saveHighScore(reached);document.getElementById('finalWave').textContent=reached;ui.show('gameOverScreen')}
function pos(ev){let r=canvas.getBoundingClientRect();return{x:(ev.clientX-r.left)*canvas.width/r.width,y:(ev.clientY-r.top)*canvas.height/r.height}}
canvas.addEventListener('click',ev=>{if(!running||paused)return;let p=pos(ev),hit=towers.find(t=>Math.hypot(t.x-p.x,t.y-p.y)<22);if(hit){selectedTower=hit;showTowerPanel();return}selectedTower=null;hideTowerPanel();if(isOnPath(p.x,p.y,path)){ui.message('길 위에는 타워를 배치할 수 없어요');return}let info=TOWER_TYPES[selectedType];if(money<info.price){ui.message('돈이 모자라요');return}towers.push(new Tower(p.x,p.y,selectedType));money-=info.price;ui.stats(money,lives,wave.number)});
function showTowerPanel(){let panel=document.getElementById('towerPanel'),t=selectedTower;panel.classList.remove('hidden');document.getElementById('selectedTowerName').textContent=TOWER_TYPES[t.type].name+' Lv.'+t.level;document.getElementById('towerStats').innerHTML='<p>공격력: '+t.damage+' · 사거리: '+Math.round(t.range)+'</p><p>업그레이드: '+t.upgradeCost()+' 골드</p>';}
function hideTowerPanel(){document.getElementById('towerPanel').classList.add('hidden')}
document.querySelectorAll('.tower-choice').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.tower-choice').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');selectedType=b.dataset.type;selectedTower=null;hideTowerPanel()}));
document.getElementById('upgradeButton').addEventListener('click',()=>{if(!selectedTower)return;let cost=selectedTower.upgradeCost();if(money<cost){ui.message('돈이 모자라요');return}money-=selectedTower.upgrade();ui.stats(money,lives,wave.number);showTowerPanel()});
document.getElementById('sellButton').addEventListener('click',()=>{if(!selectedTower)return;money+=Math.floor(selectedTower.totalCost*.7);towers.splice(towers.indexOf(selectedTower),1);selectedTower=null;hideTowerPanel();ui.stats(money,lives,wave.number)});
document.getElementById('pauseButton').addEventListener('click',()=>{if(!running)return;paused=!paused;document.getElementById('pausedLabel').classList.toggle('hidden',!paused);document.getElementById('pauseButton').textContent=paused?'▶ 다시':'Ⅱ 일시정지'});
document.getElementById('startButton').addEventListener('click',()=>{ui.show('gameScreen');reset()});document.getElementById('retryButton').addEventListener('click',()=>{ui.show('gameScreen');reset()});
